@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,600;0,700;1,600;1,700&display=swap');
:root{color-scheme:dark;--ink:#f4f0dc;--muted:#a3ad92;--gold:#e8bc69;--green:#182b21;--line:rgba(222,224,193,.15)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#0d1713;color:var(--ink);font-family:'DM Sans',sans-serif;touch-action:none;user-select:none;-webkit-user-select:none}body{display:grid;place-items:center;padding:18px}.game-shell{width:min(1120px,100%);height:min(820px,100%);display:flex;flex-direction:column;background:#111d17;border:1px solid rgba(228,222,184,.17);box-shadow:0 28px 90px #0008;overflow:hidden}.topbar{height:68px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;padding:0 24px;border-bottom:1px solid var(--line);background:#121f19}.brand{display:flex;align-items:center;gap:12px}.brand-mark{font-size:25px;color:var(--gold);line-height:1}.brand strong,.brand small{display:block;letter-spacing:.16em}.brand strong{font-size:12px;font-weight:700}.brand small{font:9px 'DM Mono',monospace;color:#8f9b86;margin-top:3px}.top-actions{display:flex;align-items:center;gap:12px}.objective{font:10px 'DM Mono',monospace;color:#bac2ac;letter-spacing:.05em;margin-right:10px}.sun-mark{color:var(--gold);font-size:15px;margin-right:7px}.icon-btn{width:34px;height:34px;border-radius:50%;border:1px solid var(--line);color:#c6cfb7;background:transparent;font-size:16px;cursor:pointer}.icon-btn:hover{background:#ffffff12}.play-area{position:relative;flex:1;min-height:0;overflow:hidden;background:#172b20}canvas{display:block;width:100%;height:100%;touch-action:none}.hud{position:absolute;left:22px;right:22px;top:17px;display:flex;align-items:center;justify-content:space-between;pointer-events:none}.hearts{display:flex;gap:5px;color:#efad86;font-size:17px;text-shadow:0 1px 9px #ed926c66}.heart-lost{opacity:.22}.progress,.clock{height:32px;display:flex;align-items:center;gap:7px;padding:0 12px;border:1px solid #dfe4c526;background:#0a150f91;border-radius:20px;backdrop-filter:blur(8px);font:10px 'DM Mono',monospace;color:#dce1ce}.progress-icon{font-size:16px;color:var(--gold)}.progress b{font-size:12px;color:var(--gold)}.progress-divider{color:#697a68}.clock{min-width:74px;justify-content:center}.clock-dot{width:6px;height:6px;background:#d8b867;border-radius:50%;box-shadow:0 0 8px #f4c874}.clock.urgent .clock-dot{background:#ed886e;box-shadow:0 0 8px #ed886e}.hint{position:absolute;top:59px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#c5cfb6;font:10px 'DM Mono',monospace;text-shadow:0 1px 5px #000;opacity:.78;pointer-events:none}.touch-controls{position:absolute;left:0;right:0;bottom:15px;display:flex;justify-content:space-between;align-items:flex-end;padding:0 20px;pointer-events:none}.dpad{width:132px;height:132px;position:relative;pointer-events:auto}.pad{position:absolute;width:43px;height:43px;border:1px solid #e8e8ce38;background:#101b16b8;color:#e5e3cb;border-radius:13px;font-size:14px;backdrop-filter:blur(5px);touch-action:none;box-shadow:0 3px 14px #0003}.pad:active,.pad.pressed{background:#d5b86b88;color:white}.pad.up{left:44px;top:0}.pad.down{left:44px;bottom:0}.pad.left{left:0;top:44px}.pad.right{right:0;top:44px}.action-controls{display:flex;gap:12px;align-items:flex-end;pointer-events:auto}.action{width:61px;height:61px;border:1px solid #e8e8ce42;border-radius:50%;color:#fff3d4;background:#132119bf;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;box-shadow:0 4px 18px #0003;touch-action:none}.action span{font-size:24px;line-height:24px}.action small{font:8px 'DM Mono',monospace;letter-spacing:.06em;color:#d3d9bd}.light-action{border-color:#e8bc6977;background:#564325a8}.run-action{width:52px;height:52px;margin-bottom:3px}.run-action span{font-size:27px}.action:active,.action.pressed{transform:scale(.94);background:#c69b4c}.overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#0e1814c9,#0d1812a8),radial-gradient(ellipse at center,#1e3327aa,transparent 70%);backdrop-filter:blur(2px);transition:opacity .45s,visibility .45s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.dialog{text-align:center;width:min(560px,90%);padding:24px 24px 18px}.eyebrow{display:flex;justify-content:center;align-items:center;gap:11px;color:#c4c6a9;font:9px 'DM Mono',monospace;letter-spacing:.18em}.eyebrow span:first-child,.eyebrow span:last-child{width:23px;height:1px;background:#b9a66888}.title-flower{font-size:30px;color:var(--gold);margin:22px auto 8px;text-shadow:0 0 24px #e4b85c99;animation:breathe 3s ease-in-out infinite}h1{font:600 clamp(55px,9vw,85px)/.79 'Playfair Display',Georgia,serif;letter-spacing:-.055em;margin:8px 0 23px;text-shadow:0 3px 25px #0008}h1 em{color:#e2c47d;font-weight:600}.intro-copy{font-size:14px;line-height:1.75;color:#d1d6c6;margin:0 auto 25px}.primary-btn{height:48px;padding:0 25px;background:#d9b866;border:0;color:#1b2117;font:700 10px 'DM Mono',monospace;letter-spacing:.12em;cursor:pointer;box-shadow:0 6px 25px #0003;transition:transform .15s,background .15s}.primary-btn:hover{background:#efce82;transform:translateY(-2px)}.primary-btn span{font-size:15px;margin-left:10px}.controls-note{margin-top:24px;color:#a6b09b;font:9px 'DM Mono',monospace}.controls-note span{color:#e7debc}.controls-note i{padding:0 6px;color:#687865;font-style:normal}.mobile-note{display:none;margin-top:17px;color:#a6b09b;font:9px 'DM Mono',monospace}.end-dialog{padding-top:30px}.end-dialog .title-flower{margin-top:25px}.end-dialog h2{font:600 clamp(34px,6vw,48px)/1.1 'Playfair Display',Georgia,serif;margin:12px 0;color:#f0e9ce}.end-dialog p{color:#c3ccb9;font-size:14px;margin:12px 0 27px}.hidden{display:none!important}.toast{position:absolute;top:91px;left:50%;transform:translate(-50%,-8px);padding:9px 16px;border:1px solid #e5c77966;background:#1a271edb;border-radius:22px;color:#f0d791;font:10px 'DM Mono',monospace;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}footer{height:38px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;padding:0 22px;color:#83917e;font:8px 'DM Mono',monospace;letter-spacing:.12em;background:#111c16}.footer-right{color:#687666}.footer-right b{font-size:12px;color:#b9a25c;margin-left:6px}@keyframes breathe{50%{transform:scale(1.13);text-shadow:0 0 30px #f0c967}}
@media(max-width:600px){body{padding:0}.game-shell{width:100%;height:100%;border:0}.topbar{height:58px;padding:0 14px}.brand{gap:8px}.brand-mark{font-size:21px}.brand strong{font-size:10px}.brand small{font-size:8px}.top-actions{gap:8px}.objective{font-size:8px;margin-right:1px;max-width:128px;white-space:nowrap}.icon-btn{width:31px;height:31px}.hud{left:13px;right:13px;top:12px}.hint{top:52px;font-size:9px}.touch-controls{bottom:max(15px,env(safe-area-inset-bottom));padding:0 14px}.dpad{width:116px;height:116px;transform:scale(.92);transform-origin:bottom left}.pad{width:39px;height:39px}.pad.up{left:39px}.pad.down{left:39px}.pad.left{top:39px}.pad.right{top:39px}.action-controls{gap:8px}.action{width:56px;height:56px}.run-action{width:48px;height:48px}.mobile-note{display:block}.controls-note{display:none}.dialog{padding-left:12px;padding-right:12px}.title-flower{margin-top:16px}.intro-copy{font-size:12px}.primary-btn{height:46px;padding:0 18px;font-size:9px}footer{height:30px;padding:0 12px;font-size:7px}.footer-right{font-size:7px}}@media(max-height:500px) and (orientation:landscape){.topbar{height:48px}.hud{top:8px}.touch-controls{bottom:6px}.dpad{transform:scale(.78);transform-origin:bottom left}.action{width:48px;height:48px}.run-action{width:43px;height:43px}.title-flower{margin:7px auto 3px;font-size:24px}h1{font-size:54px;margin:5px 0 10px}.intro-copy{font-size:11px;margin-bottom:13px}.controls-note{margin-top:12px}.mobile-note{margin-top:8px}footer{height:24px}.dialog{padding:5px}}

(() => {
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = { overlay:$('overlay'), intro:$('introDialog'), end:$('endDialog'), title:$('endTitle'), copy:$('endCopy'), kicker:$('endKicker'), icon:$('endIcon'), objective:$('objective'), count:$('count'), timer:$('timer'), hearts:$('hearts'), hint:$('hint'), toast:$('toast'), sound:$('soundBtn'), pause:$('pauseBtn') };
  const W=1900,H=1450,CAMP={x:950,y:725}, LIGHTS=[{x:345,y:300},{x:1540,y:330},{x:355,y:1120},{x:1555,y:1110}];
  const player={x:950,y:775,r:12,hp:3,stamina:100,invuln:0};
  let trees=[], flowers=[], motes=[], shades=[], keys={}, touch={up:false,down:false,left:false,right:false,run:false};
  let state='title', collected=0, time=180, last=0, camera={x:0,y:0}, pulseCooldown=0, pulseTime=0, toastTimer=0, audio=null, muted=true, lastDamage=0, hintTimer=0;
  let vw=1,vh=1,dpr=1, seed=7491;
  const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
  function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
  function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);vw=r.width;vh=r.height;canvas.width=Math.round(vw*dpr);canvas.height=Math.round(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  function onPath(x,y){return LIGHTS.some(p=>{const ax=CAMP.x,ay=CAMP.y,bx=p.x,by=p.y,dx=bx-ax,dy=by-ay,t=Math.max(0,Math.min(1,((x-ax)*dx+(y-ay)*dy)/(dx*dx+dy*dy)));return Math.hypot(x-(ax+t*dx),y-(ay+t*dy))<70})}
  function newGame(){seed=7491;player.x=CAMP.x;player.y=CAMP.y+50;player.hp=3;player.stamina=100;player.invuln=0;collected=0;time=180;pulseCooldown=0;pulseTime=0;lastDamage=0;shades=[{x:500,y:700,phase:0,stun:0},{x:1380,y:790,phase:2,stun:0}];state='playing';ui.overlay.classList.add('hidden');ui.intro.classList.add('hidden');ui.end.classList.add('hidden');ui.pause.textContent='Ⅱ';updateHud();last=performance.now()}
  function makeForest(){trees=[];flowers=[];motes=[];for(let i=0;i<230;i++){let x=40+rand()*(W-80),y=40+rand()*(H-80);if(Math.hypot(x-CAMP.x,y-CAMP.y)<125||LIGHTS.some(p=>Math.hypot(x-p.x,y-p.y)<82)||onPath(x,y)){i--;continue}trees.push({x,y,r:15+rand()*12,size:.72+rand()*.78,tone:rand(),phase:rand()*8})}for(let i=0;i<340;i++)flowers.push({x:rand()*W,y:rand()*H,size:1+rand()*2.2,a:.1+rand()*.28,tone:rand()})for(let i=0;i<55;i++)motes.push({x:rand()*W,y:rand()*H,phase:rand()*7,speed:.2+rand()*.7})}
  function circleHits(x,y,r){if(x<r||y<r||x>W-r||y>H-r)return true;for(const t of trees)if(Math.hypot(x-t.x,y-t.y)<r+t.r*.48)return true;return false}
  function movePlayer(dx,dy,dt){if(!dx&&!dy)return;const m=Math.hypot(dx,dy);dx/=m;dy/=m;const running=(keys.ShiftLeft||keys.ShiftRight||touch.run)&&player.stamina>2;const speed=running?218:143;if(running)player.stamina=Math.max(0,player.stamina-31*dt);else player.stamina=Math.min(100,player.stamina+19*dt);const nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(!circleHits(nx,player.y,player.r))player.x=nx;if(!circleHits(player.x,ny,player.r))player.y=ny}
  function startPulse(){if(state!=='playing'||pulseCooldown>0)return;pulseCooldown=2.8;pulseTime=.38;sound(330,.12,'sine');for(const s of shades)if(dist(s,player)<205){s.stun=2.4;s.x+=((s.x-player.x)/(dist(s,player)||1))*30}showToast('A little light goes a long way')}
  function sound(freq,dur,type='sine'){if(muted)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch(e){}}
  function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.6}
  function winGame(won){state=won?'won':'lost';ui.overlay.classList.remove('hidden');ui.intro.classList.add('hidden');ui.end.classList.remove('hidden');ui.kicker.textContent=won?'THE WOODS ARE QUIET':'THE NIGHT GOT TOO CLOSE';ui.icon.textContent=won?'✧':'☾';ui.title.textContent=won?'You found your way.':'The forest keeps its secrets.';ui.copy.textContent=won?'The little lights glow safely by the fire.':'Every path leads somewhere. Take another walk?';$('againBtn').textContent=won?'WALK AGAIN ↗':'TRY AGAIN ↗';ui.pause.textContent='Ⅱ'}
  function updateHud(){ui.count.textContent=collected;ui.hearts.innerHTML=Array.from({length:3},(_,i)=>`<span class="${i>=player.hp?'heart-lost':''}">♥</span>`).join('');const mm=Math.floor(time/60),ss=Math.floor(time%60);ui.timer.textContent=`${String(mm).padStart(2,'0')}:${String(ss).padStart(2,'0')}`;ui.timer.parentElement.classList.toggle('urgent',time<35);ui.objective.textContent=collected<4?`Find the lost lights · ${4-collected} left`:'Bring the lights back to camp'}
  function update(dt){if(state!=='playing')return;time-=dt;if(time<=0){time=0;updateHud();winGame(false);return}pulseCooldown=Math.max(0,pulseCooldown-dt);pulseTime=Math.max(0,pulseTime-dt);player.invuln=Math.max(0,player.invuln-dt);toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');hintTimer-=dt;
    let dx=(keys.ArrowRight||keys.KeyD?1:0)-(keys.ArrowLeft||keys.KeyA?1:0)+(touch.right?1:0)-(touch.left?1:0);let dy=(keys.ArrowDown||keys.KeyS?1:0)-(keys.ArrowUp||keys.KeyW?1:0)+(touch.down?1:0)-(touch.up?1:0);movePlayer(dx,dy,dt);
    LIGHTS.forEach((p,i)=>{if(!p.got&&dist(player,p)<30){p.got=true;collected++;sound(610+i*115,.32,'triangle');showToast(['A warm little memory.','The dark feels smaller.','You are almost home.','The forest exhales.'][i]);updateHud();if(collected===4)hintTimer=7}});
    for(const s of shades){if(s.stun>0){s.stun-=dt;continue}const d=dist(s,player),chase=d<460;let vx,vy;if(chase){vx=(player.x-s.x)/(d||1);vy=(player.y-s.y)/(d||1)}else{s.phase+=dt*.32;vx=Math.cos(s.phase);vy=Math.sin(s.phase)}const speed=chase?73:24,nx=s.x+vx*speed*dt,ny=s.y+vy*speed*dt;if(!circleHits(nx,s.y,15))s.x=nx;else s.phase+=1.3;if(!circleHits(s.x,ny,15))s.y=ny;else s.phase+=1.1;if(d<29&&player.invuln<=0){player.hp--;player.invuln=1.6;s.x-=vx*45;s.y-=vy*45;sound(110,.22,'sawtooth');showToast('A shadow brushed past you');updateHud();if(player.hp<=0){winGame(false);return}}}
    if(collected===4&&dist(player,CAMP)<55){sound(720,.5,'triangle');winGame(true);return}if(collected===4&&hintTimer>0)ui.hint.textContent='The old camp is waiting — follow the glowing trail';else ui.hint.textContent=collected===4?'Find the campfire in the middle of the woods.':'The forest is listening.';camera.x=Math.max(0,Math.min(W-vw,player.x-vw/2));camera.y=Math.max(0,Math.min(H-vh,player.y-vh/2));updateHud()}
  function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,vw,vh);ctx.save();ctx.translate(-camera.x,-camera.y);ctx.fillStyle='#1b3325';ctx.fillRect(camera.x,camera.y,vw,vh);
    // soft forest floor
    for(const f of flowers){if(f.x<camera.x-4||f.y<camera.y-4||f.x>camera.x+vw+4||f.y>camera.y+vh+4)continue;ctx.fillStyle=f.tone>.72?`rgba(202,180,111,${f.a})`:`rgba(130,163,111,${f.a})`;ctx.beginPath();ctx.arc(f.x,f.y,f.size,0,Math.PI*2);ctx.fill()}
    // faint wanderer's paths
    for(const p of LIGHTS){ctx.beginPath();ctx.moveTo(CAMP.x,CAMP.y);ctx.quadraticCurveTo((CAMP.x+p.x)/2+Math.sin(p.y)*85,(CAMP.y+p.y)/2+45,p.x,p.y);ctx.strokeStyle='rgba(183,167,105,.09)';ctx.lineWidth=44;ctx.lineCap='round';ctx.stroke();ctx.strokeStyle='rgba(200,190,130,.08)';ctx.lineWidth=1;ctx.setLineDash([3,14]);ctx.stroke();ctx.setLineDash([])}
    // campfire
    ctx.save();ctx.translate(CAMP.x,CAMP.y);const fire=1+Math.sin(performance.now()*.009)*.08;ctx.fillStyle='#d49345';ctx.beginPath();ctx.ellipse(0,5,21,11,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#66513a';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-10,6);ctx.lineTo(9,-1);ctx.moveTo(-8,-2);ctx.lineTo(10,7);ctx.stroke();const flame=ctx.createRadialGradient(0,-5,2,0,-5,22*fire);flame.addColorStop(0,'#fff2ae');flame.addColorStop(.24,'#f8b451');flame.addColorStop(1,'#e7782b00');ctx.fillStyle=flame;ctx.beginPath();ctx.arc(0,-5,22*fire,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffd47c';ctx.beginPath();ctx.ellipse(0,-7,4,9*fire,0,0,Math.PI*2);ctx.fill();ctx.restore();
    for(const [i,p] of LIGHTS.entries()){if(p.got)continue;const bob=Math.sin(performance.now()*.002+i*2)*4;ctx.save();ctx.translate(p.x,p.y+bob);const g=ctx.createRadialGradient(0,0,2,0,0,44);g.addColorStop(0,'#ffe9a7aa');g.addColorStop(1,'#f4cf6900');ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,44,0,7);ctx.fill();ctx.rotate(performance.now()*.0007+i);ctx.fillStyle='#f8da88';ctx.beginPath();ctx.moveTo(0,-11);ctx.lineTo(5,0);ctx.lineTo(0,11);ctx.lineTo(-5,0);ctx.closePath();ctx.fill();ctx.restore()}
    for(const s of shades){ctx.save();ctx.translate(s.x,s.y);ctx.globalAlpha=s.stun>0?.3:.85;ctx.fillStyle='#09120e';ctx.shadowColor=s.stun>0?'#ead58a':'#08100c';ctx.shadowBlur=s.stun>0?24:9;ctx.beginPath();ctx.ellipse(0,2,15,19,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle=s.stun>0?'#fff0aa':'#d18b65';ctx.beginPath();ctx.arc(-5,-3,1.8,0,7);ctx.arc(5,-3,1.8,0,7);ctx.fill();ctx.restore()}
    for(const t of trees){if(t.x<camera.x-50||t.y<camera.y-60||t.x>camera.x+vw+50||t.y>camera.y+vh+50)continue;const s=t.size;ctx.save();ctx.translate(t.x,t.y);ctx.scale(s,s);ctx.fillStyle='#10231a';ctx.beginPath();ctx.ellipse(4,17,17,9,0,0,7);ctx.fill();ctx.fillStyle='#503e2b';ctx.fillRect(-4,-2,8,24);ctx.fillStyle=t.tone>.5?'#254631':'#203d2d';ctx.beginPath();ctx.arc(0,-7,21,0,7);ctx.fill();ctx.fillStyle=t.tone>.5?'#31543a':'#294a34';ctx.beginPath();ctx.arc(-8,-15,13,0,7);ctx.arc(8,-16,13,0,7);ctx.fill();ctx.fillStyle='rgba(176,190,127,.10)';ctx.beginPath();ctx.arc(-8,-20,7,0,7);ctx.fill();ctx.restore()}
    // player: hooded traveler
    ctx.save();ctx.translate(player.x,player.y);if(player.invuln>0&&Math.floor(performance.now()/90)%2===0)ctx.globalAlpha=.4;ctx.fillStyle='#09140f77';ctx.beginPath();ctx.ellipse(2,12,12,7,0,0,7);ctx.fill();ctx.fillStyle='#d3b86e';ctx.beginPath();ctx.arc(0,0,15,0,7);ctx.fill();ctx.fillStyle='#456b4a';ctx.beginPath();ctx.arc(0,1,10,0,7);ctx.fill();ctx.fillStyle='#dfc895';ctx.beginPath();ctx.arc(0,-3,5.5,0,7);ctx.fill();ctx.fillStyle='#29372b';ctx.beginPath();ctx.arc(0,-7,7,Math.PI,0);ctx.fill();ctx.fillStyle='#fff0bb';ctx.beginPath();ctx.arc(8,3,2,0,7);ctx.fill();ctx.restore();
    // darkness vignette and lantern vision
    const darkness=ctx.createRadialGradient(player.x,player.y,75,player.x,player.y,Math.max(vw,vh)*.82);darkness.addColorStop(0,'rgba(4,11,8,.02)');darkness.addColorStop(.42,'rgba(5,12,9,.16)');darkness.addColorStop(1,'rgba(3,8,6,.64)');ctx.fillStyle=darkness;ctx.fillRect(camera.x,camera.y,vw,vh);
    const light=ctx.createRadialGradient(player.x,player.y,25,player.x,player.y,190);light.addColorStop(0,'rgba(241,209,139,.11)');light.addColorStop(1,'rgba(236,199,119,0)');ctx.fillStyle=light;ctx.fillRect(player.x-190,player.y-190,380,380);
    if(pulseTime>0){const r=(.38-pulseTime)*580;ctx.beginPath();ctx.arc(player.x,player.y,r,0,7);ctx.strokeStyle=`rgba(255,230,155,${pulseTime/.38*.7})`;ctx.lineWidth=4;ctx.stroke()}
    ctx.restore();}
